import { GeoCatchment, type CatchmentClient, type CatchmentSite } from "@/components/lumesec/geo-catchment";

const sites: CatchmentSite[] = [
  { id: "ams", label: "Amsterdam", lat: 52.37, lon: 4.9 },
  { id: "iad", label: "Ashburn", lat: 39.04, lon: -77.49 },
  { id: "sin", label: "Singapore", lat: 1.35, lon: 103.82 },
];

const clients: CatchmentClient[] = [
  { lat: 48.86, lon: 2.35, weight: 1200 },
  { lat: 40.71, lon: -74.01, weight: 2100 },
  { lat: 35.68, lon: 139.65, weight: 900 },
];

export function Example() {
  return <GeoCatchment sites={sites} clients={clients} defaultValue="ams" onActiveChange={(ids) => console.log(ids)} />;
}
